//! Byte-level helpers standing in for the `std::string` operations the C++
//! parser used: `find`, `substr` and a `tolower` transform.

/// Index of the first occurrence of `needle`, mirroring `std::string::find(char)`.
pub fn find_byte(haystack: &[u8], needle: u8) -> Option<usize> {
    haystack.iter().position(|&b| b == needle)
}

/// Index of the first occurrence of `needle`, mirroring
/// `std::string::find(const char*)`. An empty needle matches at 0.
pub fn find_sub(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if needle.len() > haystack.len() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
}

/// Lowercase `A`..=`Z` and leave every other byte untouched.
///
/// The C++ side lowercases the scheme with the `<cctype>` `tolower` in the
/// default "C" locale, where only the ASCII uppercase letters have a mapping;
/// bytes `0x80`..=`0xFF` pass through verbatim. An exhaustive sweep of all 255
/// possible single-byte schemes against the reference binary confirms this.
pub fn ascii_lower(input: &[u8]) -> Vec<u8> {
    input
        .iter()
        .map(|&b| {
            if b.is_ascii_uppercase() {
                b + 32
            } else {
                b
            }
        })
        .collect()
}

/// `isspace` in the "C" locale: space, tab, newline, vertical tab, form feed,
/// carriage return. Used to reproduce the leading-whitespace skip that
/// `std::stoi` inherits from `strtol`.
pub fn is_c_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_first_occurrence_only() {
        assert_eq!(find_byte(b"a#b#c", b'#'), Some(1));
        assert_eq!(find_byte(b"abc", b'#'), None);
        assert_eq!(find_sub(b"a://b://c", b"://"), Some(1));
        assert_eq!(find_sub(b"http:/a.com", b"://"), None);
        assert_eq!(find_sub(b"://x", b"://"), Some(0));
    }

    #[test]
    fn lowercases_ascii_only() {
        assert_eq!(ascii_lower(b"HtTp"), b"http".to_vec());
        assert_eq!(ascii_lower(b"1A B"), b"1a b".to_vec());
        assert_eq!(ascii_lower(&[0xc3, 0x84, b'B']), vec![0xc3, 0x84, b'b']);
    }
}

