//! Port-number conversion.
//!
//! The C++ parser converts the text after the authority's first `:` with a
//! `std::stoi` guarded by a `try`/`catch`, then range-checks the result:
//!
//! ```text
//! try { int v = std::stoi(port_text); if (v >= 0 && v <= 65535) port_ = v; }
//! catch (...) { /* port_ stays -1 */ }
//! ```
//!
//! `NO_PORT` (-1) therefore covers three distinct situations, all observed on
//! the reference binary:
//!
//! * no `:` in the authority at all — `http://a.com` -> `-1`
//! * `std::invalid_argument`, i.e. no digits to consume — `http://a.com:abc` -> `-1`
//! * a value outside `0..=65535`, whether it fit in an `int` or overflowed and
//!   raised `std::out_of_range` — `http://a.com:65536` and
//!   `http://a.com:2147483647` both -> `-1`

use crate::url_parser::bytes::is_c_space;

/// Sentinel the C++ code reports when no usable port is present.
pub const NO_PORT: i32 = -1;

/// Highest port the C++ parser accepts.
pub const MAX_PORT: i64 = 65535;

/// Accumulation ceiling. Once the running value passes this we know it can
/// never land back inside `0..=65535`, so we stop accumulating and avoid
/// overflowing. This collapses `std::stoi`'s `out_of_range` case and the
/// explicit range check into one rejection, which is sound because both
/// produce `-1`.
const ACCUMULATE_CEILING: i64 = MAX_PORT + 1;

/// Reproduce `std::stoi` (base 10) followed by the `0..=65535` range check,
/// returning [`NO_PORT`] wherever the C++ code would have caught an exception
/// or rejected the value.
///
/// `std::stoi` delegates to `strtol`, so it skips leading whitespace, accepts a
/// single optional sign, consumes the longest run of decimal digits, and
/// silently ignores whatever trailing garbage follows — `":  +0080abc"` yields
/// `80`, and `"80.5"` yields `80`.
pub fn parse_port(text: &[u8]) -> i32 {
    let mut i = 0usize;

    // strtol: skip leading whitespace.
    while i < text.len() && is_c_space(text[i]) {
        i += 1;
    }

    // strtol: at most one sign character.
    let mut negative = false;
    if i < text.len() && (text[i] == b'+' || text[i] == b'-') {
        negative = text[i] == b'-';
        i += 1;
    }

    // strtol: the longest run of base-10 digits.
    let digits_start = i;
    let mut value: i64 = 0;
    while i < text.len() && text[i].is_ascii_digit() {
        if value <= ACCUMULATE_CEILING {
            value = value * 10 + i64::from(text[i] - b'0');
        }
        i += 1;
    }

    // No digits at all: std::stoi throws std::invalid_argument.
    if i == digits_start {
        return NO_PORT;
    }

    let value = if negative { -value } else { value };
    if (0..=MAX_PORT).contains(&value) {
        value as i32
    } else {
        NO_PORT
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_plain_and_signed_decimals() {
        assert_eq!(parse_port(b"8080"), 8080);
        assert_eq!(parse_port(b"0"), 0);
        assert_eq!(parse_port(b"1"), 1);
        assert_eq!(parse_port(b"65535"), 65535);
        assert_eq!(parse_port(b"+80"), 80);
        assert_eq!(parse_port(b"-0"), 0);
    }

    #[test]
    fn skips_whitespace_and_trailing_garbage() {
        assert_eq!(parse_port(b" 80"), 80);
        assert_eq!(parse_port(b"  80"), 80);
        assert_eq!(parse_port(b"\t80"), 80);
        assert_eq!(parse_port(b"\n80"), 80);
        assert_eq!(parse_port(b"\x0b80"), 80);
        assert_eq!(parse_port(b"\x0c80"), 80);
        assert_eq!(parse_port(b"\r80"), 80);
        assert_eq!(parse_port(b"  +0080abc"), 80);
        assert_eq!(parse_port(b"80abc"), 80);
        assert_eq!(parse_port(b"80.5"), 80);
        assert_eq!(parse_port(b"80:90"), 80);
        assert_eq!(parse_port(b"0x50"), 0);
        assert_eq!(parse_port(b"08"), 8);
        assert_eq!(parse_port(b"0080"), 80);
    }

    #[test]
    fn rejects_non_numeric() {
        assert_eq!(parse_port(b""), NO_PORT);
        assert_eq!(parse_port(b"abc"), NO_PORT);
        assert_eq!(parse_port(b"++80"), NO_PORT);
        assert_eq!(parse_port(b"+ 80"), NO_PORT);
        assert_eq!(parse_port(b":1]:8080"), NO_PORT);
    }

    #[test]
    fn rejects_out_of_range() {
        assert_eq!(parse_port(b"-80"), NO_PORT);
        assert_eq!(parse_port(b"65536"), NO_PORT);
        assert_eq!(parse_port(b"65536x"), NO_PORT);
        assert_eq!(parse_port(b"99999"), NO_PORT);
        assert_eq!(parse_port(b"2147483647"), NO_PORT);
        assert_eq!(parse_port(b"2147483648"), NO_PORT);
        assert_eq!(parse_port(b"-2147483649"), NO_PORT);
        assert_eq!(parse_port(b"6553600000000000000000000"), NO_PORT);
    }

    #[test]
    fn leading_zeros_do_not_trip_the_overflow_guard() {
        assert_eq!(parse_port(b"00000000000000065535"), 65535);
        assert_eq!(parse_port(b"0000000000000000000000"), 0);
    }
}

