        assert_eq!(parse_port(b"abc"), NO_PORT);
        assert_eq!(parse_port(b"++80"), NO_PORT);
        assert_eq!(parse_port(b"+ 80"), NO_PORT);
        assert_eq!(parse_port(b":1]:8080"), NO_PORT);
    }

    #[test]
    fn rejects_out_of_range() {
        assert_eq!(parse_port(b"-80"), NO_PORT);
        assert_eq!(parse_port(b"65536"), NO_PORT);
        assert_eq!(parse_port(b"65536x"), NO_PORT);
        assert_eq!(parse_port(b"99999"), NO_PORT);
        assert_eq!(parse_port(b"2147483647"), NO_PORT);
        assert_eq!(parse_port(b"2147483648"), NO_PORT);
        assert_eq!(parse_port(b"-2147483649"), NO_PORT);
        assert_eq!(parse_port(b"6553600000000000000000000"), NO_PORT);
    }

    #[test]
    fn leading_zeros_do_not_trip_the_overflow_guard() {
        assert_eq!(parse_port(b"00000000000000065535"), 65535);
        assert_eq!(parse_port(b"0000000000000000000000"), 0);
    }
}

