/// A parsed URL, mirroring `url_parser::URL` from the C++ header.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: Vec<u8>,
    host: Vec<u8>,
    port: i32,
    path: Vec<u8>,
    query: Vec<u8>,
