            Some(slash) => (&after_scheme[..slash], &after_scheme[slash..]),
            None => (after_scheme, &after_scheme[after_scheme.len()..]),
        };

        // 5. Discard userinfo, up to and including the first `@`.
        let authority = match find_byte(authority, b'@') {
            Some(at) => &authority[at + 1..],
            None => authority,
        };

        // 6. Split host from port at the first `:`.
        let (host, port) = match find_byte(authority, b':') {
            Some(colon) => (&authority[..colon], parse_port(&authority[colon + 1..])),
            None => (authority, NO_PORT),
        };

