mod tests {
    use super::*;

    /// Assert all five fields at once against the reference binary's output.
    fn check(input: &str, scheme: &str, host: &str, port: i32, path: &str, query: &str) {
        let url = URL::new(input.as_bytes());
        let actual = (
            String::from_utf8_lossy(url.scheme()).into_owned(),
            String::from_utf8_lossy(url.host()).into_owned(),
            url.port(),
            String::from_utf8_lossy(url.path()).into_owned(),
            String::from_utf8_lossy(url.query()).into_owned(),
        );
        let expected = (
            scheme.to_string(),
            host.to_string(),
            port,
            path.to_string(),
            query.to_string(),
        );
        assert_eq!(actual, expected, "input {input:?}");
    }

    #[test]
    fn documented_examples() {
        check("http://example.com", "http", "example.com", -1, "", "");
        check("https://example.com", "https", "example.com", -1, "", "");
        check("http://localhost", "http", "localhost", -1, "", "");
        check("http://127.0.0.1", "http", "127.0.0.1", -1, "", "");
        check("http://example.com:8080", "http", "example.com", 8080, "", "");
    }

    #[test]
    fn full_url() {
        check(
            "http://a.com:8080/a/b/c.html?x=1&y=2",
            "http",
            "a.com",
            8080,
            "/a/b/c.html",
            "x=1&y=2",
        );
        check(
            "http://user:pass@a.com:8080/p?q#f",
            "http",
            "a.com",
            8080,
            "/p",
            "q",
        );
    }

    #[test]
    fn fragment_is_stripped_first_over_the_whole_input() {
        check("http#x://a.com/p", "", "", -1, "http", "");
        check("http://a#b.com/p", "http", "a", -1, "", "");
        check("http://a.com/p#f?q=1", "http", "a.com", -1, "/p", "");
        check("a#b?c", "", "", -1, "a", "");
        check("a#b#c", "", "", -1, "a", "");
        check("#x", "", "", -1, "", "");
        check("x#", "", "", -1, "x", "");
        check("http://a.com/#", "http", "a.com", -1, "/", "");
    }

    #[test]
    fn query_is_split_before_the_scheme_is_located() {
        check("a?b://c", "", "", -1, "a", "b://c");
        check("a?b://c/d", "", "", -1, "a", "b://c/d");
        check("a?b?c", "", "", -1, "a", "b?c");
        check("http://a.com?q=1", "http", "a.com", -1, "", "q=1");
        check("http://a.com:8080?q=1", "http", "a.com", 8080, "", "q=1");
        check("http://a.com/a?b?c", "http", "a.com", -1, "/a", "b?c");
        check("http://a.com?a#b?c", "http", "a.com", -1, "", "a");
        check("http://a.com/p?", "http", "a.com", -1, "/p", "");
    }

    #[test]
    fn scheme_requires_the_full_separator_and_is_lowercased() {
        check("HTTP://A.COM", "http", "A.COM", -1, "", "");
        check("HtTp://A.CoM/PaTh?Q=X", "http", "A.CoM", -1, "/PaTh", "Q=X");
