        check("//a.com", "", "", -1, "//a.com", "");
        check(":", "", "", -1, ":", "");
        check("::", "", "", -1, "::", "");
        check("//", "", "", -1, "//", "");
        check("///", "", "", -1, "///", "");
        check("////", "", "", -1, "////", "");
    }

