    fn port_is_taken_from_the_first_colon_only() {
        check("http://a.com:", "http", "a.com", -1, "", "");
        check("http://a.com:abc", "http", "a.com", -1, "", "");
        check("http://a.com:80:90/p", "http", "a.com", 80, "/p", "");
        // A colon inside the path is never a port.
        check("http://a.com/p:80", "http", "a.com", -1, "/p:80", "");
        // The unbracketed first-colon scan mangles IPv6, exactly as C++ does.
        check("http://[::1]:8080/p", "http", "[", -1, "/p", "");
    }

    #[test]
    fn no_default_port_is_ever_inferred() {
        for scheme in ["http", "https", "ftp", "ssh", "ws", "wss", "file"] {
            let url = URL::new(format!("{scheme}://a").as_bytes());
            assert_eq!(url.port(), -1, "scheme {scheme} must not gain a default port");
        }
    }

    #[test]
    fn paths_are_never_normalized_or_decoded() {
        check("http://a.com/./../x", "http", "a.com", -1, "/./../x", "");
        check("http://a.com//p", "http", "a.com", -1, "//p", "");
        check("http://a.com/p%20q", "http", "a.com", -1, "/p%20q", "");
        check("http://a.com/p q", "http", "a.com", -1, "/p q", "");
        check("http://a.com/p/q/", "http", "a.com", -1, "/p/q/", "");
        check("http://a.com:8080/", "http", "a.com", 8080, "/", "");
    }

    #[test]
    fn non_utf8_bytes_survive_unchanged() {
        // "\xc3\x84B://H\xc3\x96ST/P?Q": only the ASCII `B` in the scheme folds.
        let url = URL::new(b"\xc3\x84B://H\xc3\x96ST/P?Q");
        assert_eq!(url.scheme(), &[0xc3, 0x84, b'b']);
        assert_eq!(url.host(), b"H\xc3\x96ST");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), b"/P");
        assert_eq!(url.query(), b"Q");
    }
}

