//! Entry point — a direct port of `tests/test5.cpp`.
//!
//! ```cpp
//! int main(int argc, char* argv[]) {
//!     if (argc < 2) return 1;
//!     std::string url = argv[1];
//!     url_parser::URL parser(url);
//!     std::cout << parser.scheme() << std::endl;
//!     std::cout << parser.host()   << std::endl;
//!     std::cout << parser.port()   << std::endl;
//!     std::cout << parser.path()   << std::endl;
//!     std::cout << parser.query()  << std::endl;
//!     return 0;
//! }
//! ```
//!
//! Build either way:
//!
//! ```text
//! rustc -O test5.rs -o test5     # standalone
//! cargo build --release          # as the `test5` bin target
//! ```

// Pull the library in by path so this file also compiles standalone with a bare
// `rustc test5.rs`, with no `--extern` and no Cargo involvement.
#[path = "src/url_parser/mod.rs"]
mod url_parser;

use std::env;
use std::ffi::OsString;
use std::io::{self, Write};
use std::process::ExitCode;

use crate::url_parser::URL;

/// Borrow an argument's raw bytes.
///
/// `argv` on Unix is a sequence of arbitrary NUL-terminated byte strings, and
/// `std::string` accepts all of them. `env::args()` would panic on an argument
/// that is not valid UTF-8, where the C++ program parses it happily, so we take
/// the `OsString` form of the same API and read the bytes directly.
#[cfg(unix)]
fn arg_bytes(arg: &OsString) -> &[u8] {
    use std::os::unix::ffi::OsStrExt;
    arg.as_os_str().as_bytes()
}

/// Non-Unix fallback: these platforms have no byte-oriented `argv` to borrow.
#[cfg(not(unix))]
fn arg_bytes(arg: &OsString) -> std::borrow::Cow<'_, [u8]> {
    match arg.to_str() {
        Some(text) => std::borrow::Cow::Borrowed(text.as_bytes()),
        None => std::borrow::Cow::Owned(arg.to_string_lossy().into_owned().into_bytes()),
    }
}

/// `std::cout << field << std::endl` for a raw byte field.
fn write_field<W: Write>(out: &mut W, field: &[u8]) -> io::Result<()> {
    out.write_all(field)?;
    out.write_all(b"\n")
}

fn main() -> ExitCode {
    let args: Vec<OsString> = env::args_os().collect();
    if args.len() < 2 {
        return ExitCode::from(1);
    }

    let url = URL::new(&arg_bytes(&args[1]));

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let result = (|| -> io::Result<()> {
        write_field(&mut out, url.scheme())?;
        write_field(&mut out, url.host())?;
        write_field(&mut out, url.port().to_string().as_bytes())?;
        write_field(&mut out, url.path())?;
        write_field(&mut out, url.query())?;
        out.flush()
    })();

    // A closed stdout makes C++ silently drop the writes rather than abort;
    // match that instead of panicking inside a `println!`.
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(_) => ExitCode::SUCCESS,
    }
}

